    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32        5        8        0
    //    simd3        4        8        0
    // Totals...
    // yes simd        9       16        0
    //  no simd       17       32        0
    fn geometric_product(self, other: AntiMysteryDipoleInversion) -> Self::Output {
        use crate::elements::*;
        VersorOdd::from_groups(
            // e41, e42, e43, scalar
            ((other.group1().yzx() * self.group0().zxy()) + (self.group0().xyx() * other.group0().wwy()) + (self.group0().yzz() * other.group0().zxw())
                - (other.group1().zxy() * self.group0().yzx())
                - (self.group0().zxy() * other.group0().yzx()))
            .with_w(self[e321] * other[e321] * -1.0),
            // e23, e31, e12, e45
            (other.group1() * self.group0().www() * Simd32x3::from(-1.0)).with_w(0.0),
            // e15, e25, e35, e1234
            Simd32x3::from(0.0).with_w(
                (self[e423] * other[e415]) + (self[e431] * other[e425]) + (self[e412] * other[e435])
                    - (self[e423] * other[e1])
                    - (self[e431] * other[e2])
                    - (self[e412] * other[e3]),
            ),
            // e4235, e4315, e4125, e3215
            (other.group0().xyz() * self.group0().www()).with_w(0.0),
        )
    }
