impl GeometricProduct<MultiVector> for RoundPointAtOrigin {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32        4       20        0
    //    simd3        4        8        0
    //    simd4        4        6        0
    // Totals...
    // yes simd       12       34        0
    //  no simd       32       68        0
    fn geometric_product(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([-(other[e4] * self[e5]) - (other[e5] * self[e4]), (other[e1234] * self[e5]) + (other[e3215] * self[e4])]),
            // e1, e2, e3, e4
            Simd32x4::from([other[e41] * self[e5] * -1.0, other[e42] * self[e5] * -1.0, other[e43] * self[e5] * -1.0, other[e45] * self[e4]])
                + (self.group0().xx().with_zw(self[e4], other[scalar]) * other.group4().with_w(self[e4])),
            // e5
            (other[scalar] * self[e5]) - (other[e45] * self[e5]),
            // e41, e42, e43, e45
            (Simd32x4::from(self[e4]) * other.group1().xyz().with_w(other[e5])) - (self.group0().xx().with_zw(self[e4], self[e5]) * other.group6().xyz().with_w(other[e4])),
            // e15, e25, e35
            -(Simd32x3::from(self[e5]) * other.group1().xyz()) - (Simd32x3::from(self[e5]) * other.group6().xyz()),
            // e23, e31, e12
            -(Simd32x3::from(self[e4]) * other.group8()) - (Simd32x3::from(self[e5]) * other.group7()),
            // e415, e425, e435, e321
            Simd32x4::from([other[e41] * self[e5], other[e42] * self[e5], other[e43] * self[e5], other[e1234] * self[e5] * -1.0])
                + (Simd32x4::from(self[e4]) * other.group4().with_w(other[e3215])),
            // e423, e431, e412
            (Simd32x3::from(self[e4]) * other.group5()) + (Simd32x3::from(self[e4]) * other.group9().yzw()),
            // e235, e315, e125
            (Simd32x3::from(self[e5]) * other.group5()) - (Simd32x3::from(self[e5]) * other.group9().yzw()),
            // e1234, e4235, e4315, e4125
            (Simd32x4::from(self[e4]) * Simd32x4::from([other[e321], other[e235], other[e315], other[e125]]))
                - (Simd32x4::from([other[e12345], other[e423], other[e431], other[e412]]) * self.group0().with_zw(self[e5], self[e5])),
            // e3215
            -(other[e12345] * self[e5]) - (other[e321] * self[e5]),
        )
    }
}
